// Package nacmodel identifies the upstream Catalyst Center model boundary.
// Recognition is not schema validation or permission to reconcile a section.
// Runtime parsing does not resolve defaults. Explicit offline exporters qualify
// individual resource expressions; full schema validation remains upstream.
package nacmodel

const (
	Format     = "netascode-catalyst-center"
	Stripe     = "catalyst_center"
	Version    = "0.5.0"
	Repository = "https://github.com/netascode/terraform-catalystcenter-nac-catalystcenter"
	Revision   = "a435555fe828f03cf3311d52fe1ab6572a247916"
)

// Section describes configuration support, distinct from operational inventory
// and SWIM. SourceFile identifies the pinned upstream consumer of this section.
type Section struct {
	// PartialReport lists bounded read/plan features; it never upgrades the
	// whole section to configuration parity.
	PartialReport     []string `json:"partialReport,omitempty"`
	PartialApply      []string `json:"partialApply,omitempty"`
	Name              string   `json:"name"`
	SourceFile        string   `json:"sourceFile"`
	ConfigurationRead bool     `json:"configurationRead"`
	Plan              bool     `json:"plan"`
	Apply             bool     `json:"apply"`
	Prune             bool     `json:"prune"`
}

// Catalog returns independent copies. Whole-section execution flags remain
// false until complete parity; PartialApply describes bounded native execution.
func Catalog() []Section {
	return []Section{
		{Name: "sites", SourceFile: "cc_sites.tf", PartialReport: []string{"area attributes", "building attributes", "floor geometry and planned-AP selected position/radio state; native image bytes remain unobservable"}, PartialApply: []string{"area/building/floor create and attribute updates with global section ownership, task correlation and read-back; opt-in bounded bulk creation uses the same journal with source-bound member/ancestor recovery, failed/uncertain batch fencing and ordinary UUID-bound updates; optional keyed singular creator/latest site baselines compose with synchronous image uploads and planned-AP edits; new public AP creates atomically retain observed floor/AP identities, with identity-loss/replacement fences and complete-tree acknowledged-task recovery and complete in-memory native AP snapshots; unmapped Update fields are refused and the observed antenna sensor flag is preserved, without granting creator or deletion authority; opt-in keyed AP observations and bounded latest-state receipts reuse the site comparison key, bind prior and expected result MACs, refuse external drift/downgrade and gate floor changes affecting retained protected APs until a verified handoff exists; catalog-compatible AP type updates preserve native radios and validate all retained bands/antennas even when omitted from source; compatible APIW6300DC/APIW6300AC forward/reverse updates have native keyed qualification; Retain only; radio replacement, public prune/delete, installed actors and full parity remain unqualified"}},
		{Name: "network_settings", SourceFile: "cc_network_settings.tf", PartialReport: []string{"site-bound NTP, DHCP, DNS, timezone and banner profiles (explicit versus inherited)", "site-bound wired/wireless collection, SNMP, syslog and NetFlow telemetry profiles", "site-bound AAA/ISE metadata (no shared-secret comparison)", "global IPv4/IPv6 pools and site reservations", "global CLI, HTTPS read/write and SNMPv2/v3 credential metadata (no credential-value comparison)", "named site credential assignments with local/inherited/disabled distinction"}, PartialApply: []string{"site-bound NTP, DHCP, DNS, timezone, banner and telemetry profiles using shared ownership, task correlation and read-back; global IP pools and site reservations with allocation preflight and owned UUID/task receipts; pure-IPAM owned source pruning with child-before-parent deletion, task/absence-backed tombstones and later explicit recreation; omitted/explicit empty pool lists follow the pinned empty-selection semantics inside an explicit network_settings object; mixed/CR-deletion cleanup, owner handoff and adoption pending; versioned global CLI, HTTPS read/write and SNMPv2/v3 credential create/update using shared projections and journal plus metadata-only NOAUTHNOPRIV create/update ownership; combined credential definitions, supported settings and assignments with complete downstream preflight and credential-receipt ordering; existing area/building/floor named credential assignments with site/credential UUID binding; explicit-null removal gated pending verified inheritance support; settings and credentials retain omitted resources"}},
		{Name: "network_profiles", SourceFile: "cc_network_profiles.tf", PartialReport: []string{"switching profiles, unique template references and existing-site assignments"}, PartialApply: []string{"switching profile create/update and additive site assignments through the shared task journal; template/site UUID binding; global scope, existing dependencies and Retain only"}},
		{Name: "fabric", SourceFile: "cc_fabric.tf", PartialReport: []string{"global unanchored L3 virtual network and IP transit definitions; bounded fabric/site/zone, membership, handoff/port and multicast observations; associations retained"}, PartialApply: []string{"global unanchored L3 virtual network and IP/BGP transit create through shared journal; Retain only; bounded fabric site/zone, L3 membership, L2 network and anycast creation reuse the shared journal; public physical-group handoff/port creation and multicast VN-to-replication sequencing have fixture qualification; broader updates/removal, SDA control-plane and anchor behavior and live fabric qualification pending"}},
		{Name: "templates", SourceFile: "cc_templates.tf", PartialReport: []string{"template project names/descriptions, tag definitions and identity-bound uncommitted regular/composite definitions with source-bound file content"}, PartialApply: []string{"template project, regular/composite draft create/update and verified commits with member-version dependencies and shared journal; tag create/update and additive template associations; Retain only; system-tag mutations and device deployment pending"}},
		{Name: "inventory", SourceFile: "cc_device_provision.tf", PartialReport: []string{"global-credential-reference discovery metadata, terminal job state and sanitized per-job device outcome counts", "inventory tag definitions and ASSIGN site/tag membership and explicit role/source comparison; bounded wired provisioning and embedded-controller settings observations; broader provisioning report coverage pending"}, PartialApply: []string{"global-credential-reference discovery create, standalone or combined with template/tag execution, with task-to-job correlation and completion/no-op checks; discovery-only owned replacement stops/removes the exact job ID before create, including active jobs, with known-task recovery; creation receipts attest native resource creation while unchanged intent still waits for Complete/Inactive before InSync while independent cohort creates/prunes can progress after full preflight; pure-discovery owned source pruning supports explicit/default-empty lists, exact task/absence tombstones and later-revision recreation; inventory-tag and combined template/inventory discovery paths retain canonical group-prefixed creation/replacement receipts and scoped Unknown recovery; mixed pruning, unqualified nested/private device paths, inline credentials, adoption and CR-deletion cleanup pending; device outcomes observed in report mode", "tag create/update through shared executor and cross-section ownership exclusion; bounded admitted site/role/tag assignment, wired provision/reprovision, template deployment, RMA mark/owned cleanup and embedded-controller enable/settings updates have fixture coverage; Retain only except explicitly supported owned cleanup; full device onboarding, replacement and live actor qualification pending"}},
		{Name: "wireless", SourceFile: "cc_wireless.tf", PartialReport: []string{"global interface names/VLAN IDs, pre-auth ACLs, ordered power profiles, pinned 802.11be definitions anchor groups, RF profiles and public AP-profile metadata"}, PartialApply: []string{"global interface, pre-auth ACL, power-profile, 802.11be, anchor-group, RF-profile and AP-profile create/update with shared journal and UUID-bound update readback; combined preflight and power-before-AP ordering; versioned AP password projections and durable receipts; Retain only; device deployment and other wireless resources pending"}},
		{Name: "lan_automation", SourceFile: "cc_lan_automation.tf"},
		{Name: "system_settings", SourceFile: "cc_system_settings.tf", PartialReport: []string{"external authentication enabled flag/custom AAA attribute, explicit AAA/ISE server metadata and UUID-correlated ISE integration status; credential comparison excluded"}, PartialApply: []string{"external authentication flag/custom AAA attribute through the shared synchronous journal", "non-ISE AAA create/update and explicit write-only credential rotation through authorized projections and UUID-bound receipts; combined server-before-external-auth execution through the shared journal; versioned RADIUS key-wrapping executor (live API readback compatibility unresolved); versioned ISE registration/password rotation and UUID-correlated integration through shared journal (live ISE qualification pending); global scope and Retain only"}},
		{Name: "authentication_templates", SourceFile: "cc_authentication_templates.tf", PartialReport: []string{"global Open, Closed and Low Impact profiles; no fabric overrides"}, PartialApply: []string{"global built-in profile updates with UUID binding and shared task journal; Retain only; live mutations pending qualification"}},
		{Name: "feature_templates", SourceFile: "cc_wireless.tf", PartialReport: []string{"wireless RRM FRA and CleanAir design attributes, protected-system-template inventory"}, PartialApply: []string{"RRM FRA and CleanAir create/update through existing task journal and UUID-bound readback; 25-instance summary paging; protected system designs retained; FRA and CleanAir reuse selected-state snapshots and one-use dispatch to refuse stale or replayed prepared writes; combined writes recheck the original snapshots of all selected collections, including converged companions, without extra planning/no-op inventory passes; CleanAir same-UUID 2.4/5/6 GHz band updates with native six-direction executor/public-manifest qualification and separate real-API CRD persistence; FRA native qualification covers both band pairs, all sensitivity enums, freeze/status transitions and interval limits; public manifest field transitions have separate real-API persistence qualification; acknowledged FRA and CleanAir Update Unknown tasks resume observation for selected root/group names and original UUIDs without replay; a combined native manifest qualifies twelve retained update tasks with per-revision mutation counts; new Creates use versioned intent identities and atomic owner/source/task/UUID creator receipts with whole-missing-set capacity preflight and mandatory receipt-gated release; acknowledged Create Unknown recovery is supported, while retained legacy Creates and taskless outcomes stay fenced; imports are not adopted; owned Updates use versioned effect identities and atomic task/UUID/desired-state applied records, replacing one row while preserving immutable creators, with capacity and receipt-required release; new creator/applied records also retain a canonical complete-native-state digest from the same verified detail response, including unmanaged attributes; legacy records are not retroactively fingerprinted; section-only opt-in source pruning requires original UUID and unchanged complete native state, refuses profile references/incomplete metadata, and publishes task/UUID/absence tombstones through the existing receipt journal; acknowledged Delete Unknown recovery and native combined cleanup are qualified; newer-input recreation uses explicit predecessor operation/cohort-digest bindings, absence checks, new UUID proof and atomic archival of the prior lifecycle; two native recreate/update/prune cycles retain complete ancestry and recover acknowledged tasks without replay; feature-only CR deletion supports manager-enrolled finalizers and status-only worker cleanup through the same owned pruning executor, with deletion/spec-bound operations, original-task observation, receipt/native-absence completion proof and manager-only metadata release; native CR cleanup is qualified; cross-owner handoff, parent-controller deletion, installed recovery and device deployment remain pending"}},
	}
}

func Sections() []string {
	catalog := Catalog()
	names := make([]string, len(catalog))
	for i, section := range catalog {
		names[i] = section.Name
	}
	return names
}
